require "cybertrain/test"
require "cybertrain/generator/console_emitter"

# Gen::ConsoleEmitter writes gen/console.rb, the tables `./app console`
# reaches the generated models through. Text only: CRuby-portable (the
# fixture's gen/console.rb is compiled by test/gen_routes_compiles.rb).
test "two models: scope, records and create arms, the names, the four builders" do
  assert_equal <<~'RUBY', Cybertrain::Gen::ConsoleEmitter.emit(["Article", "Comment"])
    # Generated by `spin run gen` from db/schema.rb. Do not edit.
    require "cybertrain/console"

    module Gen
      module Console
        MODEL_NAMES = ["Article", "Comment"]

        # Article -> Article.all, as a Cybertrain::Relation.
        def self.scope(name)
          case name
          when "Article" then Article.all
          when "Comment" then Comment.all
          else Cybertrain::Console.unknown_model(name)
          end
        end

        # The records of a relation scope returned, as Array<Cybertrain::Model>.
        def self.records(relation)
          out = Array.new(0) { Cybertrain::Model.new }
          case relation
          when ArticleRelation then relation.to_a.each { |r| out << r }
          when CommentRelation then relation.to_a.each { |r| out << r }
          end
          out
        end

        # Article.create(attrs); attrs: Hash<Symbol, polymorphic>.
        def self.create(name, attrs)
          case name
          when "Article" then Article.create(attrs)
          when "Comment" then Comment.create(attrs)
          else Cybertrain::Console.unknown_record(name)
          end
        end
      end
    end

    Cybertrain::Console.scope_builder = ->(name) { Gen::Console.scope(name) }
    Cybertrain::Console.records_builder = ->(relation) { Gen::Console.records(relation) }
    Cybertrain::Console.create_builder = ->(name, attrs) { Gen::Console.create(name, attrs) }
    Cybertrain::Console.model_names = Gen::Console::MODEL_NAMES
  RUBY
end

test "no models: scope and create always raise, records is empty" do
  source = Cybertrain::Gen::ConsoleEmitter.emit(Array.new(0) { "" })
  assert_includes source, "    MODEL_NAMES = Array.new(0) { \"\" }\n"
  assert_includes source, "    def self.scope(name)\n      Cybertrain::Console.unknown_model(name)\n    end\n"
  assert_includes source, "    def self.create(name, attrs)\n      Cybertrain::Console.unknown_record(name)\n    end\n"
  assert_includes source, "    def self.records(relation)\n      out = Array.new(0) { Cybertrain::Model.new }\n      out\n    end\n"
  assert source.end_with?("Cybertrain::Console.model_names = Gen::Console::MODEL_NAMES\n")
end

Cybertrain::Test.run!
